import type { Metadata } from "next";
import { getFormatter, getTranslations } from "next-intl/server";

import { requireWorkspace } from "@intelligo-dev/auth";
import { getBillingOverview } from "@intelligo-dev/billing";

import { Link } from "@/i18n/navigation";
import { Card } from "@/components/ui/card";
import { CreditBundles } from "@/components/billing/credit-bundles";
import { formatMoney } from "@/lib/format-money";
import { PortalButton } from "@/components/billing/portal-button";
import {
  PageHeader,
  PageHeaderContent,
  PageHeaderDescription,
  PageHeaderTitle,
} from "@/components/ui/page-header";
import {
  StatCard,
  StatCardFooter,
  StatCardHeader,
  StatCardLabel,
  StatCardValue,
} from "@/components/ui/stat-card";

export async function generateMetadata(): Promise<Metadata> {
  const t = await getTranslations("billing-settings");
  return { title: t("meta.title") };
}

/**
 * Billing settings page — server component.
 *
 * Reads the caller's role from `requireWorkspace()` and the
 * role-shaped billing state from `getBillingOverview` (`@intelligo-dev/billing`
 * — moved server-side out of what used to be a client component's own
 * three-way branch). `member` and `admin` get a read-only summary;
 * `owner` gets the full plan/credit/payment-method view.
 *
 * `overview.subscription.status` is left untranslated and rendered
 * verbatim: `@intelligo-dev/billing` types it as a plain `string` mirrored
 * from Stripe's own (larger-than-documented) subscription status
 * vocabulary, not a closed enum, so keying a translation off it risks
 * a missing-message error for any status this deployment hasn't
 * localized. Revisit this once the package narrows that type to a
 * closed union.
 */
export default async function BillingSettingsPage() {
  const t = await getTranslations("billing-settings");
  const format = await getFormatter();
  const { workspace, membership } = await requireWorkspace();
  const overview = await getBillingOverview({
    workspaceId: workspace.id,
    role: membership.role,
  });

  return (
    <div className="space-y-6">
      <PageHeader>
        <PageHeaderContent>
          <PageHeaderTitle level={2}>{t("page.title")}</PageHeaderTitle>
          <PageHeaderDescription>
            {t("page.description", { workspaceName: workspace.name })}
          </PageHeaderDescription>
        </PageHeaderContent>
      </PageHeader>

      {overview.role === "member" && (
        <Card className="space-y-2 p-6">
          <p className="text-sm font-medium">
            {t("member.currentPlan", { planName: overview.planName })}
          </p>
          <p className="text-sm text-muted-foreground">{t("member.note")}</p>
        </Card>
      )}

      {overview.role === "admin" && (
        <Card className="space-y-2 p-6">
          <p className="text-sm font-medium">
            {t("admin.currentPlan", { planName: overview.planName })}
          </p>
          <p className="text-sm text-muted-foreground">{t("admin.note")}</p>
        </Card>
      )}

      {overview.role === "owner" && (
        <div className="space-y-6">
          <Card className="space-y-4 p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-muted-foreground">
                  {t("owner.currentPlanLabel")}
                </p>
                <p className="text-2xl font-semibold">{overview.planName}</p>
              </div>
              {overview.subscription && (
                <span className="text-sm capitalize text-muted-foreground">
                  {overview.subscription.status}
                </span>
              )}
            </div>

            {overview.subscription?.currentPeriodEnd && (
              <p className="text-xs text-muted-foreground">
                {t("owner.renews", {
                  date: format.dateTime(
                    overview.subscription.currentPeriodEnd,
                    {
                      dateStyle: "medium",
                    }
                  ),
                })}
              </p>
            )}

            <div className="flex flex-wrap items-center gap-3 pt-2">
              <Link
                href="/pricing"
                className="text-sm font-medium underline underline-offset-4"
              >
                {t("owner.viewAllPlans")}
              </Link>
              {overview.subscription?.stripeCustomerId && (
                <PortalButton>{t("owner.manageSubscription")}</PortalButton>
              )}
            </div>
          </Card>

          <StatCard>
            <StatCardHeader>
              <StatCardLabel>{t("owner.creditBalanceLabel")}</StatCardLabel>
              <StatCardValue>
                {/* An amount that names its own currency — it used to
                    be a bare number followed by the word "credits",
                    whatever the deployment actually billed in. */}
                {overview.creditBalance
                  ? formatMoney(format, overview.creditBalance)
                  : "—"}
              </StatCardValue>
            </StatCardHeader>
            <StatCardFooter>{t("owner.creditBalanceNote")}</StatCardFooter>
          </StatCard>

          <CreditBundles currentBalance={overview.creditBalance} />

          {overview.subscription?.stripeCustomerId && (
            <Card className="space-y-2 p-6">
              <p className="text-sm font-medium">
                {t("owner.paymentMethodTitle")}
              </p>
              <p className="text-sm text-muted-foreground">
                {t("owner.paymentMethodNote")}
              </p>
              <PortalButton variant="outline">
                {t("owner.openPortal")}
              </PortalButton>
            </Card>
          )}
        </div>
      )}
    </div>
  );
}

import { Card } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";

export default function BillingSettingsLoading() {
  return (
    <div className="space-y-6">
      <div>
        <Skeleton className="h-7 w-32" />
        <Skeleton className="mt-2 h-4 w-64" />
      </div>

      <Card className="space-y-4 p-6">
        <Skeleton className="h-4 w-24" />
        <Skeleton className="h-8 w-40" />
        <Skeleton className="h-9 w-40" />
      </Card>

      <Card className="space-y-4 p-6">
        <Skeleton className="h-4 w-32" />
        <Skeleton className="h-8 w-24" />
      </Card>

      <div className="grid grid-cols-1 gap-4 md:grid-cols-3">
        {[1, 2, 3].map((i) => (
          <Card key={i} className="space-y-4 p-6">
            <Skeleton className="h-6 w-32" />
            <Skeleton className="h-8 w-20" />
            <Skeleton className="h-9 w-full" />
          </Card>
        ))}
      </div>
    </div>
  );
}

"use client";

/**
 * Triggers a Stripe Customer Portal session for managing payment
 * methods, invoices, and subscription changes, and redirects the
 * browser there.
 */

import { useState } from "react";
import { useTranslations } from "next-intl";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";

import { createPortalSession } from "@/actions/billing";

interface PortalButtonProps {
  children?: React.ReactNode;
  className?: string;
  variant?: "default" | "outline" | "ghost";
}

export function PortalButton({
  children,
  className,
  variant = "default",
}: PortalButtonProps) {
  const t = useTranslations("billing-settings");
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleClick = async () => {
    setError(null);
    setIsLoading(true);

    const result = await createPortalSession();

    if (!result.success) {
      setError(result.error);
      setIsLoading(false);
      return;
    }

    window.location.href = result.data.url;
  };

  return (
    <div className="space-y-2">
      <Button
        onClick={handleClick}
        disabled={isLoading}
        className={className}
        variant={variant}
      >
        {isLoading
          ? t("portalButton.redirecting")
          : (children ?? t("portalButton.manageBilling"))}
      </Button>

      {error && (
        <Alert variant="destructive">
          <AlertDescription>{error}</AlertDescription>
        </Alert>
      )}
    </div>
  );
}

"use client";

/**
 * Displays this deployment's credit bundles (`@/lib/billing`'s
 * `CREDIT_BUNDLES`, installed by the `pricing` item) for one-time
 * purchase.
 *
 * `bundle.name` is deployment config from `CREDIT_BUNDLES`
 * (`lib/billing-config.ts`), not copy owned by this item — it is
 * rendered verbatim rather than routed through `messages/en.json`
 *; localize it in that config file if this deployment
 * needs bundle names in more than one language.
 *
 * A bundle carries two amounts and each is formatted in its own
 * currency: `price` is what the buyer pays the payment provider, and
 * `grant` is what lands in the ledger. They are not the same money —
 * a pack can cost $5 and grant ₮100,000 — and the version of this card
 * that formatted one number with the ledger's `CURRENCY` printed a
 * $1.01 pack as "₮1": right glyph, wrong money, rounded to nothing.
 *
 * A bundle still written in the older `{ credits, priceUsd }` shape is
 * read the way the ledger read it: whole units of `CURRENCY`, priced
 * in dollars.
 */

import { useState } from "react";
import { Coins } from "lucide-react";
import { useFormatter, useTranslations } from "next-intl";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";

import { createCreditPurchaseSession } from "@/actions/billing";
import { CREDIT_BUNDLES, CURRENCY } from "@/lib/billing-config";

/** Micros are millionths of one major unit. */
const MICROS_PER_UNIT = 1_000_000;

type Bundle = (typeof CREDIT_BUNDLES)[number];
type Amount = { amount: number; currency: string };

/** What the workspace receives, in the ledger's own currency. */
function grantOf(bundle: Bundle): Amount {
  return "grant" in bundle
    ? bundle.grant
    : { amount: bundle.credits * MICROS_PER_UNIT, currency: CURRENCY };
}

/** What the buyer pays, in the currency the provider charges. */
function priceOf(bundle: Bundle): Amount {
  return "price" in bundle
    ? bundle.price
    : {
        amount: Math.round(bundle.priceUsd * MICROS_PER_UNIT),
        currency: "USD",
      };
}

interface CreditBundlesProps {
  /**
   * The top-up balance, in the ledger's own currency. It was a bare
   * number the page pluralised as "N credits", whatever the deployment
   * actually billed in.
   */
  currentBalance?: Amount | null;
}

export function CreditBundles({ currentBalance }: CreditBundlesProps) {
  const t = useTranslations("billing-settings");
  const format = useFormatter();
  const [loadingId, setLoadingId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handlePurchase = async (bundleId: string) => {
    setError(null);
    setLoadingId(bundleId);

    const result = await createCreditPurchaseSession({ bundleId });

    if (!result.success) {
      setError(result.error);
      setLoadingId(null);
      return;
    }

    window.location.href = result.data.url;
  };

  return (
    <div className="space-y-4">
      <div>
        <p className="text-sm font-medium">{t("creditBundles.buyMore")}</p>
        {currentBalance && (
          <p className="text-sm text-muted-foreground">
            {t("creditBundles.currentBalance", {
              balance: format.number(currentBalance.amount / MICROS_PER_UNIT, {
                style: "currency",
                currency: currentBalance.currency,
              }),
            })}
          </p>
        )}
      </div>

      <div className="grid grid-cols-1 gap-4 md:grid-cols-3">
        {CREDIT_BUNDLES.map((bundle) => {
          const isLoading = loadingId === bundle.id;
          const grant = grantOf(bundle);
          const price = priceOf(bundle);
          return (
            <Card key={bundle.id} className="space-y-4 p-6">
              <div className="flex items-center gap-2">
                <Coins className="size-5 text-muted-foreground" />
                <p className="font-medium">{bundle.name}</p>
              </div>
              <p className="text-2xl font-semibold text-foreground">
                {format.number(grant.amount / MICROS_PER_UNIT, {
                  style: "currency",
                  currency: grant.currency,
                })}
              </p>
              <p className="text-sm text-muted-foreground">
                {t("creditBundles.oneTime", {
                  price: format.number(price.amount / MICROS_PER_UNIT, {
                    style: "currency",
                    currency: price.currency,
                  }),
                })}
              </p>
              <Button
                onClick={() => handlePurchase(bundle.id)}
                disabled={isLoading}
                variant="outline"
                className="w-full"
              >
                {isLoading
                  ? t("creditBundles.redirecting")
                  : t("creditBundles.purchase")}
              </Button>
            </Card>
          );
        })}
      </div>

      {error && (
        <Alert variant="destructive">
          <AlertDescription>{error}</AlertDescription>
        </Alert>
      )}
    </div>
  );
}

